// Synthetic mosaic only. Uses generated exact upstream methods, no decoder API.
#include "synthetic_support.hpp"
static void require(bool x,const char*m){if(!x)throw std::runtime_error(m);}
static std::vector<ushort> snapshot(LibRaw&v){return {(ushort*)v.image,(ushort*)v.image+size_t(v.width)*v.height*4};}
static void fill(LibRaw&v,int pattern){uint32_t state=0x201121;for(int y=0;y<v.height;y++)for(int x=0;x<v.width;x++){state=state*1664525u+1013904223u;int color=v.xtrans[y%6][x%6];ushort val=pattern==0?1024:pattern==1?ushort(((x/17+y/13)&1)?30000:32):pattern==2?ushort(32+(state>>18)):ushort(128+(x*19+y*7)%16000);v.image[size_t(y)*v.width+x][color]=val;}}
struct Axis{int start,last,begin,end;};
static std::vector<Axis> axis(int length){std::vector<Axis>v;for(int p=3;p<length-19;p+=496){int m=std::min(p+512,length-3)-p;if(length-p<516)m=length-p+2;v.push_back({p,p+m-1,p+std::min(p,8),p+m-8});}return v;}
static void write(const std::string&p,const std::vector<ushort>&v){std::ofstream f(p,std::ios::binary);f.write((const char*)v.data(),v.size()*2);require(bool(f),"output write");}
int main(int argc,char**argv){try{require(argc==2,"new result directory");std::string out=argv[1];omp_set_dynamic(0);int passed=0,oracleCalls=0,candidateCalls=0,baselineCalls=0;size_t maxPeak=0;std::ofstream report(out+"/cases.jsonl");int dims[][3]={{512,512,0},{521,519,1},{1009,1015,2},{1024,1024,3},{1553,1007,2}};
for(auto&d:dims)for(int passes:{1,3}){int w=d[0],h=d[1];LibRaw seed(w,h);fill(seed,d[2]);auto input=snapshot(seed);std::vector<ushort> expected=input;auto ys=axis(h),xs=axis(w);bool gotBound=false;
// Independent one-tile-at-a-time upstream oracle. Each tile starts from an
// untouched identical synthetic mosaic, executes the original tile formulas,
// writes only its region. Assemble those regions, then call original border8.
for(auto yr:ys)for(auto xr:xs){omp_set_num_threads(1);LibRaw tile(w,h,0x3C);memcpy(tile.image,input.data(),input.size()*2);tile.tileTop=yr.start;tile.tileLeft=xr.start;tile.oracle_tile(passes);oracleCalls++;require(tile.live==0,"oracle scratch leak");if(!gotBound){for(size_t i=0;i<size_t(w)*h;i++)expected[4*i+3]=tile.image[i][3];gotBound=true;}for(int y=yr.begin;y<yr.end;y++)for(int x=xr.begin;x<xr.end;x++)for(int c=0;c<3;c++)expected[4*(size_t(y)*w+x)+c]=tile.image[size_t(y)*w+x][c];tile.checkImageCanary();}
LibRaw assembled(w,h);memcpy(assembled.image,expected.data(),expected.size()*2);assembled.border_interpolate(8);expected=snapshot(assembled);auto name=std::to_string(w)+"x"+std::to_string(h)+"-p"+std::to_string(passes);write(out+"/"+name+"-oracle.u16",expected);
for(int k=0;k<4;k++){int threads=k==0?1:k==1?2:6;omp_set_num_threads(threads);LibRaw candidate(w,h,k%2?0x5A:0xA5);memcpy(candidate.image,input.data(),input.size()*2);candidate.candidate_interpolate(passes);candidateCalls++;require(candidate.live==0,"candidate output/scratch leak");require(candidate.stableChecked,"input stability check missing");require(candidate.borderCalls==1&&candidate.borderAfterCommit,"border order changed");candidate.checkImageCanary();auto result=snapshot(candidate);require(result==expected,"candidate disagrees with isolated upstream tile oracle");maxPeak=std::max(maxPeak,candidate.peak);if(k==0)write(out+"/"+name+"-candidate.u16",result);report<<"{\"fixture\":\""<<name<<"\",\"passes\":"<<passes<<",\"threadsRequested\":"<<threads<<",\"poison\":"<<int(candidate.poison)<<",\"oracleExactAll4Slots\":true,\"stableInputAtJoin\":true,\"borderAfterCommit\":true,\"allocationsPeakRequested\":"<<candidate.peak<<",\"liveAfter\":0}\n";passed++;}
// Keep differences from the unpatched serial algorithm: not an equality gate.
omp_set_num_threads(1);LibRaw old(w,h);memcpy(old.image,input.data(),input.size()*2);old.xtrans_interpolate(passes);baselineCalls++;auto oldData=snapshot(old);size_t changed=0;unsigned maxDelta=0;for(size_t i=0;i<oldData.size();i++){if((i&3)==3)continue;unsigned delta=unsigned(std::abs(int(oldData[i])-int(expected[i])));changed+=delta!=0;maxDelta=std::max(maxDelta,delta);}report<<"{\"fixture\":\""<<name<<"\",\"unpatchedSerialVsCandidateChangedRgb\":"<<changed<<",\"maxDelta\":"<<maxDelta<<",\"claim\":\"synthetic only; not stored Fuji baseline\"}\n";write(out+"/"+name+"-unpatched.u16",oldData);
}
// Out-of-memory rejects allocation before worker start; no success/partial commit.
{LibRaw candidate(512,512);fill(candidate,0);candidate.failAt=1;bool rejected=false;try{candidate.candidate_interpolate(3);}catch(int e){rejected=e==LIBRAW_EXCEPTION_ALLOC;}require(rejected&&candidate.live==0,"output allocation failure not propagated");passed++;}
// If scratch allocation fails after output success, output guard releases it.
{LibRaw candidate(512,512);fill(candidate,0);candidate.failAt=2;bool rejected=false;try{candidate.candidate_interpolate(3);}catch(int e){rejected=e==LIBRAW_EXCEPTION_ALLOC;}require(rejected&&candidate.live==0,"output allocation leaked on later failure");passed++;}
{LibRaw candidate(511,512);bool rejected=false;try{candidate.candidate_interpolate(3);}catch(int e){rejected=e==LIBRAW_EXCEPTION_IO_CORRUPT;}require(rejected&&candidate.live==0,"too-small shape not rejected");passed++;}
std::ofstream summary(out+"/summary.json");summary<<"{\"status\":\"PASS_NO_RAW_SYNTHETIC_ALGORITHM\",\"checks\":"<<passed<<",\"candidateCalls\":"<<candidateCalls<<",\"oneTileOracleCalls\":"<<oracleCalls<<",\"unpatchedCalls\":"<<baselineCalls<<",\"peakRequestedBytes\":"<<maxPeak<<",\"RAW\":0,\"nativeDecoderBuild\":0,\"T\":512,\"runtime\":\"LLVM libomp synthetic only\"}\n";std::cout<<"PASS checks="<<passed<<" candidate="<<candidateCalls<<" oracle="<<oracleCalls<<" baseline="<<baselineCalls<<"\n";return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}catch(int e){std::cerr<<"LibRaw exception "<<e<<"\n";return 2;}}
